static void note_wx ( struct pg_state * st , unsigned long addr ) { cfs_time_t npages ; npages = ( addr - st -> start_address ) / PAGE_SIZE ; if ( pcibios_enabled && st -> start_address >= PAGE_OFFSET + BIOS_BEGIN && addr <= PAGE_OFFSET + BIOS_END ) { pr_warn_once ( "x86/mm: PCI BIOS W+X mapping %lu pages\n" , npages ) ; return ; } st -> wx_pages += npages ; WARN_ONCE ( __supported_pte_mask & _PAGE_NX , "x86/mm: Found insecure W+X mapping at address %pS\n" , ( void * ) st -> start_address ) ; } 